css:
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  background: transparent;
}

.widget {
  width: 100%;
  height: 100%;
  background: transparent;
  border-radius: 20px;
  padding: 14px 14px 11px;
  position: relative;
  overflow: hidden;
  font-family: 'PingFang SC', 'Hiragino Sans', sans-serif;
  display: flex;
  flex-direction: column;
  gap: 0;
}

.stars-bg {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
}

/* 歌名：左对齐 */
.song-title {
  position: relative;
  z-index: 2;
  flex-shrink: 0;
  font-size: 14px;
  font-weight: 700;
  color: #1a1a1a;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  margin-bottom: 8px;
  text-align: center;
}

.song-title span {
  color: #888888;
  font-weight: 400;
  font-size: 12px;
}

/* 歌词区域：占组件约 1/2 高度，露出三行 */
.lyric-wrap {
  position: relative;
  z-index: 2;
  height: 88px;
  overflow: hidden;
  flex-shrink: 0;
  mask-image: linear-gradient(to bottom, transparent 0%, black 22%, black 68%, transparent 100%);
  -webkit-mask-image: linear-gradient(to bottom, transparent 0%, black 22%, black 68%, transparent 100%);
  margin-bottom: 4px;
}

.lyric-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
  transition: transform 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}

/* 歌词居中，未激活为灰色 */
.lyric-line {
  font-size: 11px;
  color: #bbbbbb;
  line-height: 1.55;
  transition: color 0.4s, font-size 0.3s, font-weight 0.3s;
  text-align: center;
}

/* 当前播放行：黑色 */
.lyric-line.active {
  color: #1a1a1a;
  font-size: 12px;
  font-weight: 600;
}

/* 进度栏：自动下沉到底部 */
.progress-wrap {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 5px;
  flex-shrink: 0;
  margin-top: auto;
  margin-bottom: 7px;
}

.time {
  font-size: 9px;
  color: #999999;
  min-width: 22px;
}

.time.right {
  text-align: right;
}

.progress-bar {
  flex: 1;
  height: 1.5px;
  background: #cccccc;
  border-radius: 2px;
  cursor: pointer;
}

.progress-fill {
  height: 100%;
  background: #1a1a1a;
  border-radius: 2px;
  width: 0%;
  transition: width 0.5s linear;
}

/* 控制按钮 */
.controls {
  position: relative;
  z-index: 2;
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-shrink: 0;
}

.btn {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.06);
  border: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.15s;
}

.btn:active {
  transform: scale(0.9);
}

.btn svg {
  width: 18px;
  height: 18px;
  fill: #aaaaaa;
  transition: fill 0.25s;
}

/* 收藏点亮：黑色 */
.btn.lit svg {
  fill: #1a1a1a;
}

/* 点赞点亮：偏粉玫瑰红 */
.btn.lit-pink svg {
  fill: #e8718a;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  background: transparent;
  width: 100%; height: 100%;
  font-family: 'Georgia', serif;
}

.widget {
  width: 100%; height: 100%;
  display: flex; flex-direction: column;
}

/* ── Tabs ── */
.tabs {
  display: flex; align-items: flex-end;
  gap: 3px; padding: 6px 8px 0;
  flex-shrink: 0;
  background: transparent;
}
.tab {
  padding: 4px 12px;
  border-radius: 8px 8px 0 0;
  font-size: 11px; font-weight: 600;
  cursor: pointer; letter-spacing: 0.3px;
  color: #fff;
  transition: all 0.2s;
}
.tab.active {
  background: #fff; color: #333;
  font-size: 12px; padding: 5px 14px;
  box-shadow: 0 -1px 4px rgba(0,0,0,0.06);
}
.tab.page1 { background: #b8c9d8; }
.tab.page1:hover { background: #a8bac8; }
.tab.page2 { background: #c8b8d0; }
.tab.page2:hover { background: #b8a8c0; }

/* ── Content ── */
.content {
  flex: 1; display: flex; gap: 8px;
  background: #fff;
  border-radius: 0 10px 10px 10px;
  padding: 10px;
  box-shadow: 0 2px 12px rgba(0,0,0,0.08);
  overflow: hidden; min-height: 0;
}

/* ── Player Card ── */
.player-card {
  width: 36%; flex-shrink: 0;
  display: flex; flex-direction: column;
  align-items: center; gap: 4px;
}
.avatar-area {
  width: 100%; flex: 1;
  background: linear-gradient(135deg, #c8c0b8 0%, #b8b0a8 50%, #c0b8b0 100%);
  border-radius: 8px; position: relative;
  overflow: hidden; min-height: 0;
  display: flex; align-items: center; justify-content: center;
}
.avatar-area::before {
  content: '';
  position: absolute; inset: 0;
  background: repeating-linear-gradient(
    -45deg,
    transparent, transparent 6px,
    rgba(255,255,255,0.18) 6px, rgba(255,255,255,0.18) 8px
  );
}
.avatar-img {
  position: absolute; inset: 0;
  width: 100%; height: 100%; object-fit: cover;
  border-radius: 8px; z-index: 2;
}
.avatar-placeholder {
  display: flex; flex-direction: column;
  align-items: center; gap: 0; z-index: 1;
  position: relative;
}
.avatar-circle {
  width: 38px; height: 38px;
  background: rgba(255,255,255,0.7);
  border-radius: 50%;
}
.avatar-body {
  width: 56px; height: 28px;
  background: rgba(255,255,255,0.7);
  border-radius: 28px 28px 0 0;
  margin-top: 2px;
}
.avatar-label {
  margin-top: 6px;
  font-size: 9px; letter-spacing: 1.5px;
  color: rgba(255,255,255,0.8);
  text-transform: uppercase;
  font-family: 'Helvetica Neue', sans-serif;
  background: rgba(0,0,0,0.15);
  padding: 2px 8px; border-radius: 10px;
}
.star {
  position: absolute; color: rgba(150,140,130,0.7);
  font-size: 13px; z-index: 1;
  animation: twinkle 3s ease-in-out infinite;
}
.s1 { top: 18%; left: 12%; animation-delay: 0s; font-size: 16px; }
.s2 { top: 25%; right: 14%; animation-delay: 0.8s; font-size: 10px; }
.s3 { bottom: 22%; left: 18%; animation-delay: 1.5s; font-size: 12px; }
@keyframes twinkle {
  0%,100% { opacity: 0.5; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.2); }
}

.username {
  font-size: 10px; letter-spacing: 2px;
  color: #888; text-transform: uppercase; font-weight: 500;
  font-family: 'Helvetica Neue', sans-serif;
}
.progress-bar {
  width: 80%; height: 3px;
  background: #e0dbd5; border-radius: 2px; overflow: hidden;
}
.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, #c0b0a0, #a89080);
  border-radius: 2px;
  animation: progress-anim 8s linear infinite;
}
@keyframes progress-anim {
  0% { width: 0% } 100% { width: 100% }
}

/* ── Controls ── */
.controls {
  display: flex; gap: 8px; align-items: center;
  padding-bottom: 2px;
}
.ctrl {
  color: #aaa; cursor: pointer;
  transition: color 0.2s; user-select: none;
  width: 14px; height: 14px;
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}
.ctrl svg { width: 100%; height: 100%; }
.ctrl:hover { color: #888; }
.ctrl.play {
  color: #999;
  background: #eee; border-radius: 50%;
  width: 22px; height: 22px;
  padding: 5px;
}
.ctrl.play svg { width: 100%; height: 100%; }
.ctrl.play:hover { background: #e0dbd5; color: #666; }

/* ── Right Panel ── */
.right-panel {
  flex: 1; display: flex; flex-direction: column; gap: 6px; min-width: 0;
}

/* Quote Banner */
.quote-banner {
  flex: 1;
  background: #f0ece8;
  border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  position: relative; overflow: hidden; min-height: 0;
}
.deco-stars {
  position: absolute; top: 10px; left: 14px;
  display: flex; gap: 3px; align-items: center;
}
.deco-stars.right { left: auto; right: 14px; }
.ds { font-size: 12px; color: #aaa; }
.ds.sm { font-size: 8px; }
.quote-text {
  font-size: 13px; color: #555;
  text-align: center; line-height: 1.7;
  font-style: italic;
  font-family: 'Georgia', serif;
  letter-spacing: 0.3px;
}
.quote-text sup { font-size: 7px; color: #aaa; }

/* Bottom Row */
.bottom-row {
  display: flex; gap: 6px;
  height: 42%; flex-shrink: 0;
}

/* Info Card */
.info-card {
  flex: 1;
  background: #fce8e8;
  border-radius: 8px;
  padding: 8px 10px;
  display: flex; flex-direction: column;
  justify-content: center; gap: 4px;
}
.info-row {
  display: flex; align-items: center; gap: 4px;
  font-family: 'Helvetica Neue', sans-serif;
}
.info-icon {
  width: 11px; height: 11px;
  display: flex; align-items: center; justify-content: center;
  color: #aaa; flex-shrink: 0;
}
.info-icon svg { width: 100%; height: 100%; }
.info-label { font-size: 10px; font-weight: 600; color: #555; min-width: 32px; }
.info-sep { font-size: 10px; color: #aaa; }
.info-val { font-size: 9px; color: #c06060; letter-spacing: 0.2px; }

/* Photo Frame */
.photo-frame {
  width: 22%;
  background: #ccc;
  border-radius: 8px; overflow: hidden;
  position: relative;
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}
.photo-img {
  position: absolute; inset: 0;
  width: 100%; height: 100%; object-fit: cover;
  z-index: 2;
}
.photo-placeholder {
  display: flex; flex-direction: column;
  align-items: center; justify-content: flex-end;
  width: 100%; height: 100%;
  padding-bottom: 6px;
  position: relative; z-index: 1;
}
.ph-sun {
  width: 14px; height: 14px;
  background: #bbb; border-radius: 50%;
  position: absolute; top: 22%; left: 50%; transform: translateX(-50%);
}
.ph-mountain {
  width: 0; height: 0;
  border-left: 14px solid transparent;
  border-right: 14px solid transparent;
  border-bottom: 18px solid #bbb;
  position: absolute; bottom: 28%; left: 50%; transform: translateX(-50%);
}
.photo-label {
  position: absolute; bottom: 6px;
  font-size: 8px; letter-spacing: 1.2px;
  color: rgba(255,255,255,0.85);
  text-transform: uppercase;
  font-family: 'Helvetica Neue', sans-serif;
  background: rgba(0,0,0,0.18);
  padding: 2px 6px; border-radius: 8px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
body { background: transparent; font-family: 'PingFang SC', 'Noto Sans SC', sans-serif; }
.card { background: #ffffff; border-radius: 18px; border: 0.5px solid rgba(0,0,0,0.08); padding: 0 0 10px; height: 100%; display: flex; flex-direction: column; gap: 0; }
.titlebar { display: flex; align-items: center; justify-content: center; position: relative; padding: 10px 16px; background: #f2f2f2; border-radius: 18px 18px 0 0; }
.back-btn { position: absolute; left: 12px; display: flex; align-items: center; justify-content: center; width: 28px; height: 28px; border-radius: 8px; cursor: pointer; border: none; background: transparent; -webkit-tap-highlight-color: transparent; transition: background 0.15s; }
.back-btn:active { background: rgba(0,0,0,0.07); }
.title-text { font-size: 15px; font-weight: 600; color: #1a1a1a; letter-spacing: 0.03em; }
.body { display: flex; flex-direction: column; gap: 4px; padding: 7px 12px 0; }
.header { display: flex; align-items: center; gap: 10px; padding-left: 5px; }
.avatar { width: 38px; height: 38px; border-radius: 50%; flex-shrink: 0; overflow: hidden; border: 1.5px solid rgba(0,0,0,0.06); background: #e8d5c4; }
.user-info { display: flex; flex-direction: column; gap: 1px; }
.username { font-size: 13px; font-weight: 600; color: #1a1a1a; letter-spacing: 0.01em; }
.handle { font-size: 11px; color: #888; }
.content { font-size: 14px; color: #1a1a1a; line-height: 1.55; letter-spacing: 0.02em; flex: 1; padding-left: 5px; }
.meta { display: flex; align-items: center; justify-content: flex-end; gap: 5px; padding-left: 5px; }
.meta-text { font-size: 11px; color: #888; }
.divider { height: 0.5px; background: rgba(0,0,0,0.07); margin: 2px 0; }
.actions { display: flex; align-items: center; }
.action-btn { flex: 1; display: flex; align-items: center; justify-content: center; gap: 5px; padding: 6px 0; border-radius: 10px; cursor: pointer; border: none; background: transparent; -webkit-tap-highlight-color: transparent; user-select: none; transition: background 0.15s; }
.action-btn:active { background: rgba(0,0,0,0.05); }
.action-label { font-size: 12px; color: #888; font-weight: 400; transition: color 0.2s; }
.action-divider { width: 0.5px; height: 20px; background: rgba(0,0,0,0.07); }
.more-btn { width: 36px; display: flex; align-items: center; justify-content: center; padding: 6px 0; cursor: pointer; border-radius: 10px; border: none; background: transparent; -webkit-tap-highlight-color: transparent; transition: background 0.15s; }
.more-btn:active { background: rgba(0,0,0,0.05); }
.popup-overlay { position: fixed; inset: 0; z-index: 100; display: none; }
.popup-overlay.show { display: block; }
.popup { position: absolute; background: rgba(255,255,255,0.97); border-radius: 14px; border: 0.5px solid rgba(0,0,0,0.1); box-shadow: 0 8px 24px rgba(0,0,0,0.12); overflow: hidden; min-width: 100px; }
.popup-item { padding: 11px 20px; font-size: 13px; color: #1a1a1a; cursor: pointer; display: flex; align-items: center; gap: 8px; transition: background 0.12s; }
.popup-item:active { background: rgba(0,0,0,0.08); }
.popup-item.danger { color: #e05c72; }
.popup-sep { height: 0.5px; background: rgba(0,0,0,0.07); }

:root {
  --m-red: #FFB3BA;
  --m-yellow: #FFDFBA;
  --m-green: #BAFFC9;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

.widget-stage {
  width: 100%; height: 100%; background: transparent;
  position: relative; overflow: hidden;
  font-family: -apple-system, sans-serif;
}

.window {
  background: #FFF; border-radius: 12px;
  position: absolute; display: flex; overflow: hidden;
  box-shadow: 0 10px 30px rgba(0,0,0,0.1);
  border: 0.5px solid rgba(0,0,0,0.1);
}

.main-window { width: 90%; height: 82%; top: 4%; left: 4%; z-index: 1; }

.sidebar {
  width: 38%; background: #F8F8F8;
  border-right: 0.5px solid #EEE;
  display: flex; flex-direction: column;
}

/* 核心修复：用 line-height: 0 彻底解决圆点不对齐 */
.window-controls, .detail-header {
  height: 36px; padding: 0 12px;
  display: flex; align-items: center; line-height: 0;
}

.traffic-lights { display: flex; gap: 6px; align-items: center; height: 10px; }

.dot { width: 10px; height: 10px; border-radius: 50%; display: inline-block; flex-shrink: 0; }
.m-red { background: var(--m-red); }
.m-yellow { background: var(--m-yellow); }
.m-green { background: var(--m-green); }

.nav-group label {
  font-size: 9px; color: #BBB; font-weight: 700;
  margin: 15px 12px 6px; display: block;
}

.nav-item {
  display: flex; align-items: center; gap: 8px;
  padding: 6px 12px; font-size: 10px; color: #444;
  white-space: nowrap;
}
.nav-item.icloud span { font-size: 9px; } /* 缩小 iCloud 字体防止换行 */

.nav-item svg { width: 14px; height: 14px; fill: none; stroke: #5EABF2; stroke-width: 2.2; flex-shrink: 0; }
.nav-item.active { background: #E7F1FF; color: #007AFF; font-weight: 600; }
.nav-item.active svg { stroke: #007AFF; }

.main-content { flex: 1; display: flex; flex-direction: column; background: #FFF; }

.top-toolbar {
  height: 36px; border-bottom: 0.5px solid #F0F0F0;
  display: flex; align-items: center; justify-content: space-between; padding: 0 12px;
}

.toolbar-left, .toolbar-right, .detail-icons { display: flex; gap: 10px; align-items: center; }

svg { stroke-linecap: round; stroke-linejoin: round; }
.top-toolbar svg, .detail-header svg { width: 14px; height: 14px; stroke: #A0A0A0; fill: none; stroke-width: 2; }

/* 核心修复：改用 padding 撑开网格高度，解决 aspect-ratio 兼容性 */
.gallery-grid {
  display: grid; grid-template-columns: repeat(3, 1fr);
  gap: 8px; padding: 12px;
}
.grid-item { position: relative; width: 100%; padding-bottom: 100%; }
.aspect-inner {
  position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background: #F2F2F2; border-radius: 8px; overflow: hidden;
}
.aspect-inner img, .full-img {
  width: 100%; height: 100%; object-fit: cover; display: block;
}

/* 预览小窗口偏移修正 */
.detail-window {
  width: 60%; height: 50%;
  top: calc(44% + 13px); 
  right: calc(4% - 18px); 
  z-index: 10; flex-direction: column;
}

.detail-header { justify-content: space-between; border-bottom: 0.5px solid #F0F0F0; }
.detail-body { flex: 1; background: #EEE; overflow: hidden; }

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  background: transparent;
  width: 100%; height: 100%;
  font-family: 'Georgia', serif;
}

.widget {
  width: calc(100% - 24px);
  height: calc(100% - 24px);
  display: flex; flex-direction: column;
  background: transparent;
  border-radius: 12px;
  padding: 20px 18px;
  margin: 12px;
  border: 1.5px dashed #c8c0b8;
  position: relative;
  overflow: visible;
  box-sizing: border-box;
}

/* ── 八个角块，骑在虚线上 ── */
.corner {
  position: absolute;
  width: 8px; height: 8px;
  border: 1.5px solid #b0a898;
  background: transparent;
  pointer-events: none;
  z-index: 2;
}
.corner.tl { top: -4px;  left: -4px; }
.corner.tr { top: -4px;  right: -4px; }
.corner.bl { bottom: -4px; left: -4px; }
.corner.br { bottom: -4px; right: -4px; }
.corner.tm { top: -4px;    left: 50%; transform: translateX(-50%); }
.corner.bm { bottom: -4px; left: 50%; transform: translateX(-50%); }
.corner.ml { left: -4px;   top: 50%;  transform: translateY(-50%); }
.corner.mr { right: -4px;  top: 50%;  transform: translateY(-50%); }

/* ── 引用区 ── */
.quote-area {
  flex: 0 0 46%;
  display: flex; flex-direction: column;
  justify-content: center;
  align-items: center;
  overflow: hidden;
}

.star-deco {
  display: flex; align-items: center; gap: 4px;
  color: #a09080;
  margin-bottom: 5px;
  justify-content: flex-start;
  width: 100%;
}
.star-icon  { width: 14px; height: 14px; }
.dot-icon   { width: 6px;  height: 6px; }
.cross-icon { width: 11px; height: 11px; }

.quote-text {
  font-size: 13px;
  font-style: italic;
  color: #2a2a2a;
  line-height: 1.65;
  letter-spacing: 0.2px;
  text-align: center;
  width: 100%;
}
.quote-text sup {
  font-size: 6px; color: #bbb; vertical-align: super;
}
.inline-cross {
  width: 9px; height: 9px;
  display: inline; vertical-align: middle;
  color: #a09080;
}

/* ── 分隔线 ── */
.divider {
  width: 100%; height: 1px;
  background: #e0d8d0;
  flex-shrink: 0;
  margin: 2px 0 4px;
}

/* ── 歌词区 ── */
.lyrics-area {
  flex: 1;
  display: flex; flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 4px;
  min-height: 0;
  overflow: hidden;
}
.lyric-line {
  font-size: 10px;
  color: #666;
  text-align: center;
  line-height: 1.6;
  letter-spacing: 0.2px;
  font-family: 'Georgia', serif;
  width: 100%;
}
.lyric-line:last-child {
  font-size: 8.5px;
  color: #aaa;
  margin-top: 2px;
  letter-spacing: 0.8px;
}

* { margin: 0; padding: 0; box-sizing: border-box; }
html, body {
  width: 100%; height: 100%;
  background: transparent;
  display: flex; align-items: center; justify-content: center;
  font-family: system-ui, sans-serif;
}
.container {
  width: 100%; height: 100%;
  display: flex; flex-direction: column;
  align-items: center; justify-content: center;
  padding: 10px 14px;
  gap: 6px;
}
.label {
  font-size: 9px; font-weight: 700;
  color: #222; letter-spacing: 0.04em;
}
.bar-wrap {
  width: 100%; height: 22px;
  border-radius: 99px;
  border: 2px solid #222;
  overflow: hidden;
  position: relative;
  background: #fff;
}
.bar-fill {
  position: absolute; top: 0; left: 0;
  height: 100%; width: 60%;
  border-radius: 99px;
  background: linear-gradient(to right, #fff 0%, #111 100%);
}
.bar-icons {
  position: absolute; top: 0; left: 0;
  width: 100%; height: 100%;
  display: flex; align-items: center;
  justify-content: space-around;
