    border-radius: 20px;                    /* 原文档圆角20px */
    padding: 0 2px;                         /* 原文档左右内边距2px */
    height: 39px;                           /* 原文档高度39px */
    width: 100%;
    position: relative;
    border: 0.5px solid rgba(255, 255, 255, 0.4);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.3);
}

/* 左右圆形按钮 —— 原文档宽高32px，磨砂半透背景 */
