* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  width: 100%; height: 100%;
  background: transparent;
  font-family: -apple-system, "PingFang SC", "Hiragino Sans", sans-serif;
}

/* 整体容器：完全透明 */
.widget {
  width: 100%; height: 100%;
  background: transparent;
  padding: 4px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

/* ── 气泡 + 箭头的外层包裹 ── */
.bubble-wrap {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  align-items: center; /* 箭头水平居中 = 对准 Home */
}

/* 半透明白色气泡框，磨砂玻璃效果 */
.bubble {
  width: 100%;
  flex: 1;
  min-height: 0;
  background: rgba(255, 255, 255, 0.78);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-radius: 18px;
  padding: 6px;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

/* 三角形箭头 */
.arrow {
  flex-shrink: 0;
  margin-top: -1px;
  width: 0;
  height: 0;
  border-left:  12px solid transparent;
  border-right: 12px solid transparent;
  border-top:   12px solid rgba(255, 255, 255, 0.78);
}

/* ── 白色联系人卡片 ── */
.card {
  flex: 1;
  min-height: 0;
  background: rgba(255, 255, 255, 0.92);
  border-radius: 12px;
  padding: 0 8px;
  display: flex;
  align-items: center;
  gap: 8px;
  overflow: hidden;
}

.avatar {
  width: 42px;
  height: 42px;
  border-radius: 10px;
  background: #ddd8d0 center/cover no-repeat;
  flex-shrink: 0;
}

.info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.top-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

/* 状态文字及新增的圆点样式 */
.status { 
  font-size: 9px; 
  color: #8e8e93; 
  display: flex; 
  align-items: center; 
  gap: 3px; 
}

.dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
}
.dot.online { background: #4cd964; }  /* 在线为绿色 */
.dot.offline { background: #b0b0b5; } /* 离线为灰色 */

.badge        { font-size: 9px; color: #8e8e93; }
.badge b      { font-weight: 700; color: #1c1c1e; }

.name {
  font-size: 12px;
  font-weight: 700;
  color: #1c1c1e;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.3;
}

.sub {
  font-size: 9px;
  color: #b0b0b5;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ── 底部导航栏 ── */
.navbar {
  height: 38px;
  flex-shrink: 0;
  background: rgba(255, 255, 255, 0.78);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: space-around;
  padding-bottom: 2px;
}

.nav-item {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  color: #a0a0a8;
}

.nav-item.active { color: #2c2c2e; }

.icon { width: 14px; height: 14px; }

.nav-item span {
  font-size: 5.5px;
  color: inherit;
  line-height: 1;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  background: transparent;
  width: 100%; height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: -apple-system, 'SF Pro Text', 'Helvetica Neue', sans-serif;
}

.widget {
  display: flex;
  flex-direction: column;
  align-items: center;
  /* 关键：整体用 filter drop-shadow，不用 box-shadow，透明底无虚影 */
  filter: drop-shadow(0 6px 18px rgba(0,0,0,0.18)) drop-shadow(0 2px 6px rgba(0,0,0,0.10));
  background: transparent;
}

/* ── 菜单主体 ── */
.menu-bar {
  display: flex;
  align-items: center;
  background: #ffffff;
  border-radius: 10px;
  padding: 0 2px;
  height: 36px;        /* 纵向缩窄：44px → 36px */
  width: fit-content;
}

/* ── 分隔线 ── */
.sep {
  width: 0.5px;
  height: 26px;
  background: rgba(0,0,0,0.15);
  flex-shrink: 0;
}

/* ── 菜单项 ── */
.menu-item {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 0 18px;     /* 横向变宽：12px → 20px */
  height: 100%;
  cursor: pointer;
  color: #1a1a1a;
  border-radius: 8px;
  transition: background 0.12s;
  white-space: nowrap;
}
.menu-item:active {
  background: rgba(0,0,0,0.06);
}

.menu-item span {
  font-size: 15px;
  font-weight: 400;
  letter-spacing: -0.2px;
}
.menu-item svg {
  width: 15px;
  height: 15px;
  flex-shrink: 0;
}

/* Delete 置灰 */
.menu-item.muted {
  color: #b0b0b0;
}

/* 箭头 */
.menu-item.chevron {
  padding: 0 10px;
  color: #3a3a3a;
}
.menu-item.chevron svg {
  width: 12px;
  height: 12px;
}

/* ── 小尾巴（与菜单同色，drop-shadow 统一投影）── */
.tail {
  width: 24px;
  height: 12px;
  background: #ffffff;
  clip-path: polygon(0 0, 100% 0, 50% 100%);
  margin-top: -1px;
}

