* { margin: 0; padding: 0; box-sizing: border-box; }
html, body {
  width: 100%; height: 100%;
  font-family: system-ui, sans-serif;
  background: #ffffff;
}
.widget {
  width: 100%; height: 100%;
  background: #ffffff;
  display: flex; flex-direction: column;
  padding: 7px 8px 5px;
  gap: 3px;
  overflow: hidden;
}
.status-bar {
  display: flex; align-items: center; justify-content: space-between;
  flex-shrink: 0; height: 11px;
}
.status-dots { display: flex; gap: 2px; align-items: center; }
.dot { width: 4px; height: 4px; border-radius: 50%; background: #bbb; }
.dot.on { background: #444; }
.status-time { font-size: 7.5px; color: #444; font-weight: 500; letter-spacing: 0.02em; }
.status-icons { display: flex; align-items: center; gap: 2px; }
.main-content {
  display: flex; flex-direction: row;
  flex: 1; min-height: 0;
}
.album-col {
  width: 50%; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
}
.album-art {
  width: 88%; aspect-ratio: 1/1;
  border-radius: 50%; background: #d4d2ce;
  overflow: hidden;
}
.album-art img { width: 100%; height: 100%; object-fit: cover; display: block; }
.track-col {
  width: 50%; flex-shrink: 0;
  display: flex; flex-direction: column;
  justify-content: space-between;
  padding-left: 4px;
}
.track-item {
  display: flex; align-items: center; gap: 4px;
  flex: 1;
  border-bottom: 0.5px solid rgba(0,0,0,0.07);
  min-width: 0; overflow: hidden;
  padding: 2px 0;
}
.track-item:last-child { border-bottom: none; }
.mini-thumb {
  width: 18%; aspect-ratio: 1/1;
  border-radius: 50%; background: #c9c7c3;
  flex-shrink: 0; overflow: hidden;
}
.mini-thumb img { width: 100%; height: 100%; object-fit: cover; display: block; }
.large-title { font-size: 7.5px; font-weight: 700; color: #222; line-height: 1.25; flex: 1; min-width: 0; }
.track-title { font-size: 6.5px; color: #555; line-height: 1.3; flex: 1; min-width: 0; }
.chev { flex-shrink: 0; opacity: 0.35; margin-left: 1px; }
.info-bar {
  background: #efefed; border-radius: 20px;
  padding: 2.5px 7px;
  display: flex; align-items: center; gap: 3px;
  flex-shrink: 0;
}
.info-text {
  font-size: 5.5px; color: #666;
  flex: 1; min-width: 0;
  display: flex; align-items: center; gap: 4px; overflow: hidden;
}
.info-text span { white-space: nowrap; }
.progress-wrap { flex-shrink: 0; padding: 0 1px; }
.progress-track { width: 100%; height: 2px; background: #d0ceca; border-radius: 99px; position: relative; }
.progress-fill { width: 55%; height: 100%; background: #888; border-radius: 99px; }
.progress-thumb {
  width: 7px; height: 7px; border-radius: 50%;
  background: #fff; border: 1.5px solid #888;
  position: absolute; top: 50%; transform: translate(-50%, -50%); left: 55%;
}
.controls {
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 1px; flex-shrink: 0; height: 22px;
}
.ctrl { display: flex; align-items: center; justify-content: center; opacity: 0.6; }
.ctrl.play {
  width: 22px; height: 22px; border-radius: 50%;
  background: #bbb; opacity: 1;
  display: flex; align-items: center; justify-content: center;
}
